


BEGIN;
SELECT pg_advisory_xact_lock(20261007, 961);
CREATE OR REPLACE FUNCTION pg_temp.cargar_referencias(lote jsonb)
RETURNS integer LANGUAGE plpgsql AS $fn$
DECLARE r jsonb; candidato uuid; cantidad integer; cargados integer := 0;
BEGIN
 FOR r IN SELECT value FROM jsonb_array_elements(lote) LOOP
  SELECT count(*),(array_agg(id))[1] INTO cantidad,candidato
  FROM public.repuestos_tecnicos
  WHERE catalogo_origen='PIONEER' AND codigo_catalogo=r->>'codigo_pioneer';
  INSERT INTO public.catalogo_referencias_fuente
   (catalogo_origen,fuente_registro_id,referencia_original,codigo_catalogo,repuesto_candidato_id,estado_revision,fuente)
  VALUES ('PIONEER',r->>'id',r->>'referencia_original',r->>'codigo_pioneer',
   CASE WHEN cantidad=1 THEN candidato ELSE NULL END,
   CASE WHEN r->>'codigo_pioneer' IS NULL THEN 'Sin código impreso'
        WHEN cantidad=0 THEN 'Sin coincidencia en aplicaciones'
        WHEN cantidad>1 THEN 'Código en varias aplicaciones'
        ELSE 'Candidato por código; cotejo pendiente' END,r)
  ON CONFLICT (catalogo_origen,fuente_registro_id) DO UPDATE SET
   referencia_original=EXCLUDED.referencia_original,codigo_catalogo=EXCLUDED.codigo_catalogo,
   repuesto_candidato_id=EXCLUDED.repuesto_candidato_id,estado_revision=EXCLUDED.estado_revision,
   fuente=EXCLUDED.fuente,updated_at=now();
  cargados:=cargados+1;
 END LOOP;
 RETURN cargados;
END;
$fn$;
